package com.lk.esp; import android.app.Activity; import android.content.Intent; import android.media.projection.MediaProjectionManager; import android.net.Uri; import android.os.Bundle; import android.provider.Settings; public class MainActivity extends Activity { @Override protected void onCreate(Bundle b) { super.onCreate(b); if (!Settings.canDrawOverlays(this)) { startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:" + getPackageName()))); } else { startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(), 1); } } @Override protected void onActivityResult(int req, int res, Intent data) { if (req == 1 && res == RESULT_OK) { startForegroundService(new Intent(this, CaptureService.class).putExtra("data", data)); startForegroundService(new Intent(this, OverlayService.class)); } } }
